package app.truemotion.vector;
import java.util.*;
import org.json.*;

/** Vector armature with keyed rigid poses and two-link IK. */
public final class VectorRig {
    public static final class Bone {
        public String id=UUID.randomUUID().toString(),name="Bone",parent="";public double x,y,angle,length=100;
        JSONObject json()throws JSONException{return new JSONObject().put("id",id).put("name",name).put("parent",parent).put("x",x).put("y",y).put("angle",angle).put("length",length);}
        static Bone read(JSONObject o)throws JSONException{Bone b=new Bone();b.id=o.getString("id");b.name=o.getString("name");b.parent=o.optString("parent");b.x=o.getDouble("x");b.y=o.getDouble("y");b.angle=o.getDouble("angle");b.length=o.getDouble("length");return b;}
    }
    public final LinkedHashMap<String,Bone> bones=new LinkedHashMap<String,Bone>();
    public final TreeMap<Integer,Map<String,double[]>> keys=new TreeMap<Integer,Map<String,double[]>>();
    public VectorRig(){keys.put(0,new LinkedHashMap<String,double[]>());}
    public double[] local(String id,int frame){Bone b=bones.get(id);if(b==null)return new double[]{0,0,0};Map.Entry<Integer,Map<String,double[]>> a=keys.floorEntry(frame),next=a==null?null:keys.higherEntry(a.getKey());double[] p=a==null?null:a.getValue().get(id);if(p==null)p=new double[]{b.x,b.y,b.angle};double[] q=next==null?null:next.getValue().get(id);if(q==null||next.getKey()==a.getKey())return p.clone();double u=(frame-a.getKey())/(double)(next.getKey()-a.getKey());return new double[]{p[0]+(q[0]-p[0])*u,p[1]+(q[1]-p[1])*u,p[2]+((q[2]-p[2]+540)%360-180)*u};}
    public double[] world(String id,int frame){return world(id,frame,new HashSet<String>());}
    private double[] world(String id,int frame,Set<String> visiting){Bone b=bones.get(id);if(b==null)return new double[]{0,0,0};if(!visiting.add(id))throw new IllegalArgumentException("Cyclic armature");double[] p=local(id,frame);if(!b.parent.isEmpty()){double[] q=world(b.parent,frame,visiting);double r=Math.toRadians(q[2]),c=Math.cos(r),s=Math.sin(r);p=new double[]{q[0]+p[0]*c-p[1]*s,q[1]+p[0]*s+p[1]*c,q[2]+p[2]};}visiting.remove(id);return p;}
    public Map<String,double[]> edit(int frame){Map<String,double[]> pose=keys.get(frame);if(pose==null){pose=new LinkedHashMap<String,double[]>();for(String id:bones.keySet())pose.put(id,local(id,frame));keys.put(frame,pose);}return pose;}
    public void set(String id,int frame,double x,double y,double angle){edit(frame).put(id,new double[]{x,y,angle});}
    public double[] inverse(String id,int frame,double x,double y){double[] b=world(id,frame);double a=Math.toRadians(b[2]),c=Math.cos(a),s=Math.sin(a);x-=b[0];y-=b[1];return new double[]{x*c+y*s,y*c-x*s};}
    public void aim(String id,int frame,double x,double y,boolean ik,boolean bend){Bone b=bones.get(id);if(b==null)return;double[] w=world(id,frame),p=local(id,frame);Bone parent=bones.get(b.parent);if(ik&&parent!=null&&Math.abs(p[0]-parent.length)<.01&&Math.abs(p[1])<.01){double[] a=world(parent.id,frame),grand=world(parent.parent,frame);float[] solved=RigMath.solve(x-a[0],y-a[1],parent.length,b.length,bend);double[] localParent=local(parent.id,frame);set(parent.id,frame,localParent[0],localParent[1],solved[0]-grand[2]);set(id,frame,p[0],p[1],solved[1]);}else{double[] a=world(b.parent,frame);set(id,frame,p[0],p[1],Math.toDegrees(Math.atan2(y-w[1],x-w[0]))-a[2]);}}
    public VectorDocument.Shape pose(VectorDocument.Shape raw,int frame){VectorDocument.Shape s=raw.copy();if(s.bone.isEmpty()||!bones.containsKey(s.bone))return s;double[] b=world(s.bone,frame);double a=Math.toRadians(b[2]),c=Math.cos(a),n=Math.sin(a);s.x=b[0]+raw.x*c-raw.y*n;s.y=b[1]+raw.x*n+raw.y*c;s.angle=raw.angle+b[2];return s;}
    public void place(VectorDocument.Shape raw,int frame,double worldX,double worldY){if(raw.bone.isEmpty()){raw.x=worldX;raw.y=worldY;}else{double[] p=inverse(raw.bone,frame,worldX,worldY);raw.x=p[0];raw.y=p[1];}}
    public JSONObject json()throws JSONException{JSONArray a=new JSONArray(),k=new JSONArray();for(Bone b:bones.values())a.put(b.json());for(Map.Entry<Integer,Map<String,double[]>> e:keys.entrySet()){JSONObject values=new JSONObject();for(Map.Entry<String,double[]> v:e.getValue().entrySet())values.put(v.getKey(),new JSONArray(Arrays.asList(v.getValue()[0],v.getValue()[1],v.getValue()[2])));k.put(new JSONObject().put("frame",e.getKey()).put("values",values));}return new JSONObject().put("bones",a).put("keys",k);}
    public static VectorRig read(JSONObject o)throws JSONException{VectorRig rig=new VectorRig();if(o==null)return rig;JSONArray a=o.getJSONArray("bones");for(int i=0;i<a.length();i++){Bone b=Bone.read(a.getJSONObject(i));rig.bones.put(b.id,b);}JSONArray k=o.getJSONArray("keys");rig.keys.clear();for(int i=0;i<k.length();i++){JSONObject key=k.getJSONObject(i),values=key.getJSONObject("values");Map<String,double[]> pose=new LinkedHashMap<String,double[]>();for(Iterator<String> it=values.keys();it.hasNext();){String id=it.next();JSONArray v=values.getJSONArray(id);pose.put(id,new double[]{v.getDouble(0),v.getDouble(1),v.getDouble(2)});}rig.keys.put(key.getInt("frame"),pose);}if(rig.keys.isEmpty())rig.keys.put(0,new LinkedHashMap<String,double[]>());rig.validate();return rig;}
    public void validate(){for(Bone b:bones.values()){for(double v:new double[]{b.x,b.y,b.angle})if(!Double.isFinite(v)||Math.abs(v)>10000000)throw new IllegalArgumentException("Invalid vector bone pose");if(!Double.isFinite(b.length)||b.length<=0||b.length>1000000||!b.parent.isEmpty()&&!bones.containsKey(b.parent))throw new IllegalArgumentException("Invalid vector bone");world(b.id,0);}for(Map.Entry<Integer,Map<String,double[]>> e:keys.entrySet()){if(e.getKey()<0)throw new IllegalArgumentException("Invalid rig frame");for(double[] p:e.getValue().values())for(double v:p)if(!Double.isFinite(v)||Math.abs(v)>10000000)throw new IllegalArgumentException("Invalid rig pose");}}
}
